const API_BASE='http://127.0.0.1:8000';
let provinceRegion={};
let data=[];
let apiMeta=null;
let projectionMeta=null;

async function loadRealData(){try{const [mr,hr,pr]=await Promise.all([fetch(`${API_BASE}/meta`),fetch(`${API_BASE}/historical/all`),fetch(`${API_BASE}/long-term-projection/meta`)]);if(!mr.ok||!hr.ok||!pr.ok)throw new Error(`ANI data service request failed (${mr.status||hr.status||pr.status}).`);apiMeta=await mr.json();projectionMeta=await pr.json();const payload=await hr.json();provinceRegion=payload.province_regions||apiMeta.province_regions||{};data=payload.records||[]}catch(error){console.error('ANI data service request failed:',error);throw error}}

const state={page:'dashboard',filterProvince:'All Provinces',filterEco:'All Ecosystems',filterYear:'All Years',query:'',historicalPage:0,request:{province:'Abra',ecosystem:'Irrigated',targetYear:2026,targetQuarter:1},nearTermRequest:{province:'Abra'},nearTermLoading:false,nearTermError:'',nearTermResult:null,projectionRequest:{province:'Abra',ecosystem:'Irrigated',horizonYears:5,targetQuarter:3,scenario:'ssp245'},projectionLoading:false,projectionError:'',projectionResult:null,processingStep:0,contextProcessingStep:0,current:null,nearestTargetAssessment:null,availabilityKey:null,availabilityFetchedAt:0,availabilityLoading:false,availabilityError:'',availableTargets:[],forecastError:'',targetSelectionManual:false};
