const saved=()=>{try{return JSON.parse(localStorage.getItem('ani-saved-forecasts')||'[]').filter(f=>f&&f.forecastId)}catch{return []}},save=f=>{localStorage.setItem('ani-saved-forecasts',JSON.stringify([f,...saved().filter(x=>x.forecastId!==f.forecastId)]));window.dispatchEvent(new CustomEvent('ani:forecasts-updated'))},removeForecast=id=>{localStorage.setItem('ani-saved-forecasts',JSON.stringify(saved().filter(f=>f.forecastId!==id)));window.dispatchEvent(new CustomEvent('ani:forecasts-updated'))};
const avg=a=>a.reduce((x,y)=>x+y,0)/a.length, fmt=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:2});
const RESULT_TYPE_BY_STATUS={PROSPECTIVE_FORECAST:'Prospective Forecast',CURRENT_QUARTER_ESTIMATE:'Current-Quarter Estimate',RETROSPECTIVE_ESTIMATE:'Retrospective Estimate'};
function manilaDate(value){const d=value?new Date(value):new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d);const get=t=>parts.find(x=>x.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`}
function temporalFor(year,quarter,referenceDate=manilaDate()){const bounds={1:['01-01','03-31'],2:['04-01','06-30'],3:['07-01','09-30'],4:['10-01','12-31']}[Number(quarter)];if(!bounds)return {temporalStatus:'RETROSPECTIVE_ESTIMATE',resultType:RESULT_TYPE_BY_STATUS.RETROSPECTIVE_ESTIMATE};const start=`${year}-${bounds[0]}`,end=`${year}-${bounds[1]}`;const temporalStatus=referenceDate<start?'PROSPECTIVE_FORECAST':referenceDate<=end?'CURRENT_QUARTER_ESTIMATE':'RETROSPECTIVE_ESTIMATE';return {temporalStatus,resultType:RESULT_TYPE_BY_STATUS[temporalStatus],targetPeriodStart:start,targetPeriodEnd:end,referenceDate,referenceTimezone:'Asia/Manila'}}
function resultTypeFor(f){if(RESULT_TYPE_BY_STATUS[f?.temporalStatus])return RESULT_TYPE_BY_STATUS[f.temporalStatus];if(Object.values(RESULT_TYPE_BY_STATUS).includes(f?.resultType))return f.resultType;return temporalFor(f.targetYear,f.targetQuarter,manilaDate(f.generatedAt)).resultType}
function resultPresentation(f){const type=resultTypeFor(f);if(type==='Prospective Forecast')return {title:'Palay Yield Forecast',metric:'Forecasted Yield',description:'Estimated provincial yield for a future target quarter.',note:''};if(type==='Current-Quarter Estimate')return {title:'Current-Quarter Palay Yield Estimate',metric:'Estimated Yield',description:'Model-based estimate for the selected provincial target quarter.',note:'The target quarter is already in progress.'};return {title:'Retrospective Palay Yield Estimate',metric:'Estimated Yield',description:'Reconstructed model estimate for a completed provincial target quarter.',note:'This target quarter has already ended. ANI is reconstructing a model-based estimate using only the pre-target historical agricultural and lagged agroclimatic inputs available to the current model. This is not a current or future forecast and is not the official observed yield for that quarter.'}}
function preferredTarget(targets){const cmp=(a,b)=>a.year-b.year||a.quarter-b.quarter;return targets.filter(x=>x.temporalStatus==='PROSPECTIVE_FORECAST').sort(cmp)[0]||targets.filter(x=>x.temporalStatus==='CURRENT_QUARTER_ESTIMATE').sort(cmp)[0]||targets.filter(x=>x.temporalStatus==='RETROSPECTIVE_ESTIMATE').sort((a,b)=>-cmp(a,b))[0]||null}
function historyCoverage(){if(!data.length)return 'Unavailable';const latest=data.reduce((a,b)=>!a||b.year>a.year||(b.year===a.year&&b.quarter>a.quarter)?b:a,null);return `${Math.min(...data.map(r=>Number(r.year)))} through Q${latest.quarter} ${latest.year}`}
const provinceCollator=new Intl.Collator('en',{sensitivity:'base'});
function sortedProvinceNames(){return Object.keys(provinceRegion).sort(provinceCollator.compare)}

async function forecast(req){
  const response=await fetch(`${API_BASE}/predict`,{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({
      province:req.province,
      ecosystem:req.ecosystem,
      target_year:req.targetYear,
      target_quarter:req.targetQuarter
    })
  });
  const payload=await response.json();
  if(!response.ok){
    throw new Error(payload.detail||'Unable to generate the selected yield estimate. Please try again.');
  }
  if(!payload.eligible){
    throw new Error(payload.reason||payload.message||'Yield estimate is unavailable for the selected period.');
  }
  return payload;
}
async function nearTermOutlook(req){
  const query=new URLSearchParams({province:req.province});
  const response=await fetch(`${API_BASE}/near-term-outlook?${query}`);
  const payload=await response.json();
  if(!response.ok)throw new Error(payload.detail||'Unable to load the near-term palay outlook.');
  return payload;
}
async function longTermProjection(req){
  const response=await fetch(`${API_BASE}/long-term-projection`,{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({
      province:req.province,
      ecosystem:req.ecosystem,
      horizon_years:Number(req.horizonYears),
      target_quarter:Number(req.targetQuarter),
      scenario:req.scenario
    })
  });
  const payload=await response.json();
  if(!response.ok)throw new Error(payload.detail||'Unable to generate the long-term projection.');
  return payload;
}

async function refreshForecastAvailability(force=false){const key=`${state.request.province}|${state.request.ecosystem}`;if(state.availabilityLoading||(!force&&state.availabilityKey===key&&Date.now()-state.availabilityFetchedAt<30000))return;state.availabilityKey=key;state.nearestTargetAssessment=null;state.availabilityLoading=true;state.availabilityError='';state.availableTargets=[];render();try{const query=new URLSearchParams({province:state.request.province,ecosystem:state.request.ecosystem}),response=await fetch(`${API_BASE}/forecast-availability?${query}`),payload=await response.json();if(!response.ok)throw new Error('Unable to check estimate availability. Please try again.');state.availableTargets=payload.availableTargets||[];state.nearestTargetAssessment=payload.nearestTargetAssessment||null;state.availabilityFetchedAt=Date.now();const selected=state.availableTargets.find(t=>t.year===state.request.targetYear&&t.quarter===state.request.targetQuarter);if(state.availableTargets.length){const preferred=preferredTarget(state.availableTargets);if(preferred&&(!state.targetSelectionManual||!selected)){state.request.targetYear=preferred.year;state.request.targetQuarter=preferred.quarter}}}catch(error){console.error('Estimate availability request failed:',error);state.availabilityError='Unable to check estimate availability. Please try again.';state.availabilityKey=key;state.availabilityFetchedAt=Date.now()}finally{state.availabilityLoading=false;if(state.page==='forecast')render()}}
const icon=x=>x?`<span class="icon">${x}</span>`:'', nav=[['dashboard','▦','Dashboard'],['forecast','◉','Generate Estimate'],['historical','▤','Historical Data'],['history','↶','Result History'],['model','▣','Model & Data'],['about','ⓘ','About ANI']];
function shell(content){const sidebarPage=(state.page==='projection'||state.page==='projection-processing'||state.page==='projection-result'||state.page==='nearterm'||state.page==='nearterm-processing'||state.page==='nearterm-result')?'forecast':state.page;return `<div class="app">${aniSidebar(sidebarPage)}<div class="content"><header class="topbar"><button class="iconBtn menuBtn" aria-label="Open navigation" aria-controls="ani-sidebar" aria-expanded="false">☰</button><strong>ANI — Provincial Palay Yield Forecasting System</strong><span class="topnote">Using PSA agricultural data, NASA POWER agroclimatic data, and XGBoost for quarterly yield estimates, with PSA standing-crop outlooks, NASA CMIP6 long-term climate scenarios, and supporting satellite, market, and PAGASA context.</span></header><main tabindex="-1">${content}</main></div></div>`}
function hero(eye,title,sub,sdg=false){return `<section class="hero hero-field"><div><span class="eyebrow">${eye}</span><h1>${title}</h1><p>${sub}</p></div>${sdg?`<div class="sdgs"><div class="sdg two"><b>2</b><span><small>PRIMARY</small><strong>SDG 2 — Zero Hunger</strong></span></div><div class="sdg thirteen"><b>13</b><span><small>SECONDARY</small><strong>SDG 13 — Climate Action</strong></span></div></div>`:''}</section>`}
