          ['Harvested Area',Number.isFinite(Number(crop.harvestedAreaThousandHa))?`${Number(crop.harvestedAreaThousandHa).toFixed(2)} thousand ha`:'Unavailable'],
          ['Harvested Share',Number.isFinite(Number(crop.harvestedSharePct))?`${Number(crop.harvestedSharePct).toFixed(1)}%`:'Unavailable'],
          ['Harvested Output',Number.isFinite(Number(crop.harvestedOutputMillionMt))?`${Number(crop.harvestedOutputMillionMt).toFixed(2)} million MT`:'Unavailable']
